#!/bin/bash
cd /testbed

# Switch to Go 1.24 (compatible with the project's dependencies)
dev-switch go 1.24

# Patch quic-go module cache incompatibility with Go >= 1.21
# The quic-go v0.33.0 used by this project has a compile-time guard and
# qtls-go1-20 v0.2.3 has a runtime struct-layout check that both fail
# on Go >= 1.21. We patch the module cache (not tracked repo files).
GO_MOD_CACHE="$(go env GOMODCACHE)"

# Remove the compile-time guard in quic-go
sed -i 's|//go:build go1.21|//go:build go1.99|' \
  "$GO_MOD_CACHE/github.com/quic-go/quic-go@v0.33.0/internal/qtls/go121.go" 2>/dev/null || true

# Replace qtls-go1-20 runtime struct compatibility check with no-op
cat > "$GO_MOD_CACHE/github.com/quic-go/qtls-go1-20@v0.2.3/unsafe.go" << 'QTLS_EOF'
package qtls

import (
	"reflect"
	"unsafe"
)

func init() {
	// patched - struct compatibility check removed for Go >= 1.21 compatibility
}

func toConnectionState(c connectionState) ConnectionState {
	return *(*ConnectionState)(unsafe.Pointer(&c))
}

func toClientSessionState(s *clientSessionState) *ClientSessionState {
	return (*ClientSessionState)(unsafe.Pointer(s))
}

func fromClientSessionState(s *ClientSessionState) *clientSessionState {
	return (*clientSessionState)(unsafe.Pointer(s))
}

func toCertificateRequestInfo(i *certificateRequestInfo) *CertificateRequestInfo {
	return (*CertificateRequestInfo)(unsafe.Pointer(i))
}

func toConfig(c *config) *Config {
	return (*Config)(unsafe.Pointer(c))
}

func fromConfig(c *Config) *config {
	return (*config)(unsafe.Pointer(c))
}

func toClientHelloInfo(chi *clientHelloInfo) *ClientHelloInfo {
	return (*ClientHelloInfo)(unsafe.Pointer(chi))
}

func structsEqual(a, b interface{}) bool {
	return true
}

func compare(a, b reflect.Value) bool {
	return true
}

func compareStruct(a, b reflect.Type) bool {
	return true
}
QTLS_EOF

# Clear the Go build cache so it picks up the patched sources
go clean -cache

# Run all target test files
# Note: For factory/processing/ we must target only the tests defined in
# processComponents_test.go since other test files in that package have
# unrelated tests that may fail.
go test -count=1 \
  -run "^TestNewProcessComponentsFactory$|^TestProcessComponentsFactory_Create$|^TestProcessComponentsFactory_CreateShouldWork$" \
  ./factory/processing/ \
  && go test -count=1 ./factory/runType/ \
  && go test -count=1 ./genesis/process/ \
  && go test -count=1 ./integrationTests/multiShard/hardFork/

